import unittest
import media_type as app

class Behavior(unittest.TestCase):
    def test_parameters(self):
        rows=[('Text/HTML;Charset="UTF-8"',('text/html',{'charset':'UTF-8'})),('application/X-Ship; boundary=DockA',('application/x-ship',{'boundary':'DockA'})),('text/plain',('text/plain',{})),('TEXT/CSV ; HEADER=present; CHARSET=utf-8',('text/csv',{'header':'present','charset':'utf-8'})),('text/plain; note=""',('text/plain',{'note':''})),('text/plain; note="A B"',('text/plain',{'note':'A B'}))]
        for s,want in rows:
            self.assertEqual(app.parse_media_type(s),want)


if __name__ == "__main__":
    unittest.main()

class ParameterSpacing(unittest.TestCase):
    def test_tabs_and_quoted_content(self):
        self.assertEqual(app.parse_media_type('TEXT/PLAIN\t;\tNOTE="  Dock=A  "\t; Zone=North'),
                         ('text/plain', {'note':'  Dock=A  ', 'zone':'North'}))
        self.assertEqual(app.parse_media_type('text/plain; note=DockA'),
                         app.parse_media_type('text/plain; NOTE="DockA"'))

