def parse_media_type(text):
    head, *parts = text.split(';')
    params = {}
    for part in parts:
        name, value = part.strip(' \t').split('=', 1)
        if value.startswith('"'):
            value = value[1:-1]
        params[name.lower()] = value
    return head.strip(' \t').lower(), params
